"""Builds self-contained main.py scripts for every SBC from the modules in src/.

Usage:  python src/build.py scripts
PT projects cannot import shared modules, so each script inlines the core.
"""
import os
import sys

SRC = os.path.dirname(os.path.abspath(__file__))
OUT = sys.argv[1] if len(sys.argv) > 1 else os.path.join(SRC, "..", "scripts")

HDR = """# HLLSet network model for Cisco Packet Tracer 9.0 (SBC-PT, Python3 project, file main.py)
# Role: {role}
# Generated by src/build.py - edit the modules in src/, not this file.
from tcp import *
from time import *
import random
import math

"""
FTR = "\n\nif __name__ == \"__main__\":\n    main()\n"


def rd(name):
    with open(os.path.join(SRC, name), encoding="utf-8") as f:
        return f.read()


def write(name, role, libs, body):
    text = HDR.format(role=role) + "\n".join(rd(l) for l in libs) + "\n" + body + FTR
    with open(os.path.join(OUT, name), "w", encoding="utf-8", newline="\n") as f:
        f.write(text)


def main():
    os.makedirs(OUT, exist_ok=True)
    core = ["hll16.py", "net.py"]
    lattice = core + ["planes.py", "morph.py"]
    write("GRID.py", "GRID", lattice, rd("role_grid.py"))
    write("DATA.py", "DATA", core, rd("role_data.py"))
    write("DISPATCHER.py", "DISPATCHER", lattice, rd("role_dispatcher.py"))
    fpga = rd("role_fpga.py")
    for i in range(1, 6):
        body = fpga.replace('BOARD = "FPGA?"            # <-- set per board: FPGA1 .. FPGA5', 'BOARD = "FPGA%d"' % i)
        write("FPGA%d.py" % i, "FPGA%d" % i, lattice, body)
    user = rd("role_user.py")
    for i in range(1, 4):
        body = (user.replace('USER = "user1"            # <-- user1 / user2 / user3', 'USER = "user%d"' % i)
                    .replace('PASSWORD = "pass1"        # <-- pass1 / pass2 / pass3', 'PASSWORD = "pass%d"' % i))
        write("USER%d.py" % i, "USER%d" % i, core + ["card.py"], body)
    print("built:", ", ".join(sorted(os.listdir(OUT))))


if __name__ == "__main__":
    main()
